   415	        // multibyte scalar is decoded incrementally from its saved state.
   416	        if !scan.utf8.incomplete()&&byte<0x80 {
   417	            let allowed=if p==scan.start{is_name_start(u32::from(byte))}else{is_name_char(u32::from(byte))};
   418	            if !allowed {if p==scan.start{return Err((XmlError::InvalidName,p))}break}
   419	        }
   420	        let decoded=work.decode(&mut scan.utf8,byte,p).map_err(|at|(XmlError::InvalidUtf8,at))?;
   421	        scan.pos+=1;
   422	        if scan.pos-scan.start>MAX_TOKEN_NAME_BYTES{return Err((XmlError::MalformedSyntax,scan.start))}
