   120	            for consumed in 1..=cut {
   121	                assert_eq!(step_measured(&mut stream),StreamStatus::Ok);
   122	                assert_eq!(stream.name_work.comparison_reads,consumed);
   123	                assert_eq!(stream.bytes_read(),frontier);
   124	            }
   125	            let comparison=stream.tag.as_ref().unwrap().comparison.unwrap();
   126	            assert_eq!(comparison.index,cut/2);
   127	            assert_eq!(comparison.left_byte.is_some(),cut%2==1);
   128	            let before=stream.name_work.total_reads;
   129	            assert_eq!(stream.step_with_cancel(1,&mut ||true),StreamStatus::Canceled);
   130	            assert_eq!(stream.name_work.total_reads,before);
   131	            assert_eq!(stream.name_work.comparison_reads,cut);
   132	            assert_eq!(stream.result(),XmlResult::default());
   133	            assert!(stream.tokens().is_empty());assert!(stream.take().is_none());
   134	        }
