 22	/// Every variable token-name source load, including comparison operands, uses
 23	/// this budget gate. The legacy `reads` counter measures scanner loads only;
 24	/// `total_reads` includes scanner and comparison loads without cursor inference.
 25	#[derive(Default)]
 26	struct NameWork {
 27	    remaining: usize, spent: usize,
 28	    #[cfg(test)] reads: usize,
 29	    #[cfg(test)] decoder_inputs: usize,
 30	    #[cfg(test)] comparison_reads: usize,
 31	    #[cfg(test)] total_reads: usize,
 32	}
 33	impl NameWork {
 34	    fn begin(&mut self, budget: usize) { self.remaining=budget;self.spent=0; }
 35	    fn load(&mut self, source: &[u8], at: usize, comparison: bool) -> Option<u8> {
 36	        if self.remaining==0{return None}
 37	        self.remaining-=1;self.spent+=1;
 38	        let byte=source[at];
 39	        #[cfg(test)] {
 40	            self.total_reads+=1;
 41	            if comparison{self.comparison_reads+=1}else{self.reads+=1}
 42	        }
 43	        #[cfg(not(test))] let _=comparison;
 44	        Some(byte)
 45	    }
 46	    fn read(&mut self, source: &[u8], at: usize) -> Option<u8> { self.load(source,at,false) }
 47	    fn decode(&mut self, utf8: &mut Utf8Scan, byte: u8, at: usize) -> Result<Option<u32>, usize> {
 48	        #[cfg(test)] { self.decoder_inputs += 1; }
 49	        utf8.push(byte, at)
 50	    }
 51	}
