322	                    match comparison.step(self.source,&mut self.name_work,cancel){
323	                        CompareStatus::Pending=>{self.tag=Some(t);return true},
324	                        CompareStatus::Canceled=>{self.tag=Some(t);self.canceled=true;return false},
325	                        CompareStatus::Different=>{self.fail(XmlError::MismatchedTag,t.start);return false},
326	                        CompareStatus::Equal=>{t.comparison=None;t.phase=TagPhase::EndBetween;if self.name_work.remaining==0{self.tag=Some(t);return true}},
327	                    }
328	                },
329	                TagPhase::Between=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1;t.separated=true}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}
330	                    if t.pos>=self.source.len(){self.fail(XmlError::MalformedSyntax,t.start);return false}
331	                    if self.source[t.pos]==b'>'{let end=t.pos+1;if !self.finish_start(&mut t,end,false,visitor){return false}return true}
332	                    if self.source.get(t.pos..t.pos+2)==Some(b"/>"){t.pos+=1;t.phase=TagPhase::EmptyClose;continue}
333	                    if !t.separated{self.fail(XmlError::MalformedSyntax,t.pos);return false}
334	                    if t.local_attrs>=self.limits.attributes_per_element||self.total_attrs>=self.limits.total_attributes{self.fail(XmlError::AttributeLimit,t.pos);return false}
335	                    t.attr_start=t.pos;t.attr_scan=Some(NameScan::new(t.pos));t.phase=TagPhase::AttrName;},
336	                TagPhase::EmptyClose=>{let end=t.pos+1;if !self.finish_start(&mut t,end,true,visitor){return false}return true},
337	                TagPhase::AttrName=>{let Some(scan)=t.attr_scan.as_mut()else{self.fail(XmlError::InvalidName,t.pos);return false};match scan_name(self.source,scan,limit,true,&mut self.name_work){Ok(Some(parts))=>{t.pos=scan.pos;
338	                    t.attr=Some(parts);t.duplicate_index=0;t.comparison=None;t.phase=TagPhase::AttrMatch;},Ok(None)=>{self.tag=Some(t);return true},Err((e,at))=>{self.fail(e,at);return false}}},
339	                TagPhase::AttrMatch=>{
340	                    if t.duplicate_index>=t.local_attrs{t.phase=TagPhase::AttrEq;if self.name_work.remaining==0{self.tag=Some(t);return true}continue}
341	                    if t.comparison.is_none(){
342	                        let Some(previous)=self.attribute_name(t.token_index,t.duplicate_index)else{self.fail(XmlError::OutputExhausted,t.attr_start);return false};
343	                        t.comparison=Some(NameCompare::new(previous,t.attr.unwrap_or_default().name));
344	                    }
345	                    match t.comparison.as_mut().unwrap().step(self.source,&mut self.name_work,cancel){
346	                        CompareStatus::Pending=>{self.tag=Some(t);return true},
347	                        CompareStatus::Canceled=>{self.tag=Some(t);self.canceled=true;return false},
348	                        CompareStatus::Equal=>{self.fail(XmlError::DuplicateAttribute,t.attr_start);return false},
349	                        CompareStatus::Different=>{t.comparison=None;t.duplicate_index+=1;if self.name_work.remaining==0{self.tag=Some(t);return true}},
350	                    }
351	                },
352	                TagPhase::AttrEq=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}if t.pos>=self.source.len()||self.source[t.pos]!=b'='{self.fail(XmlError::MalformedSyntax,t.pos);return false}t.pos+=1;t.phase=TagPhase::AttrQuote;},
353	                TagPhase::AttrQuote=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}if t.pos>=self.source.len()||!matches!(self.source[t.pos],b'\''|b'"'){self.fail(XmlError::MalformedSyntax,t.pos);return false}t.quote=self.source[t.pos];t.pos+=1;t.value_start=t.pos;t.phase=TagPhase::AttrValue;},
354	                TagPhase::AttrValue=>{let mut paused=false;while t.pos<limit&&t.pos<self.source.len()&&self.source[t.pos]!=t.quote{if cancel(){self.tag=Some(t);self.canceled=true;return false}if self.source[t.pos]==b'<'{self.fail(XmlError::MalformedSyntax,t.pos);return false}if self.source[t.pos]==b'&'{let scan=t.reference.get_or_insert_with(||RefScan::new(t.pos));match reference_step(self.source,scan,limit,&mut self.name_work){Ok(Some(end))=>{t.pos=end;t.reference=None},Ok(None)=>{paused=true;break},Err((e,at))=>{self.fail(e,at);return false}}}else{t.pos+=1}}
355	                    if paused||(t.pos==limit&&t.pos<self.source.len()){self.tag=Some(t);return true}if t.pos>=self.source.len(){self.fail(XmlError::MalformedSyntax,t.value_start-1);return false}
356	                    let Some(attr)=t.attr else{self.fail(XmlError::InvalidName,t.attr_start);return false};let tok=XmlToken{kind:TokenKind::Attribute,name:attr.name,prefix:attr.prefix,local_name:attr.local,source:span(t.attr_start,t.pos+1),value:span(t.value_start,t.pos),depth:self.depth,..XmlToken::default()};
