358	                TagPhase::EndBetween=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}if t.pos>=self.source.len()||self.source[t.pos]!=b'>'{self.fail(XmlError::MalformedSyntax,t.pos);return false}
