409	fn span(start:usize,end:usize)->XmlSpan{XmlSpan{offset:start,length:end.saturating_sub(start)}}
410	fn scan_name(source:&[u8],scan:&mut NameScan,limit:usize,qname:bool,work:&mut NameWork)->Result<Option<NameParts>,(XmlError,usize)>{
411	    while scan.pos<limit&&scan.pos<source.len(){
412	        let p=scan.pos;
413	        let Some(byte)=work.read(source,p)else{return Ok(None)};
414	        // ASCII delimiters terminate a name without consuming their byte. A
415	        // multibyte scalar is decoded incrementally from its saved state.
416	        if !scan.utf8.incomplete()&&byte<0x80 {
417	            let allowed=if p==scan.start{is_name_start(u32::from(byte))}else{is_name_char(u32::from(byte))};
418	            if !allowed {if p==scan.start{return Err((XmlError::InvalidName,p))}break}
419	        }
420	        let decoded=work.decode(&mut scan.utf8,byte,p).map_err(|at|(XmlError::InvalidUtf8,at))?;
421	        scan.pos+=1;
422	        if scan.pos-scan.start>MAX_TOKEN_NAME_BYTES{return Err((XmlError::MalformedSyntax,scan.start))}
423	        let Some(cp)=decoded else{continue};
424	        let at=scan.utf8.start;let first=at==scan.start;
425	        if !(if first{is_name_start(cp)}else{is_name_char(cp)}) {
426	            if first{return Err((XmlError::InvalidName,at))}
427	            scan.pos=at;break
428	        }
429	        scan.classification.push(cp,at-scan.start);
430	        if first{scan.leading_colon=cp==b':' as u32}
431	        if let Some(colon)=scan.first_colon {
432	            if at==colon+1{scan.local_first_valid=Some(is_name_start(cp))}
433	        }
434	        if cp==b':' as u32 {
435	            if qname&&scan.first_colon.is_some(){return Err((XmlError::InvalidName,scan.first_colon.unwrap_or(at)))}
436	            if scan.first_colon.is_none(){scan.first_colon=Some(at)}
437	        }
438	        scan.trailing_colon=cp==b':' as u32;
439	    }
440	    let p=scan.pos;
441	    if p==source.len()&&scan.utf8.incomplete(){return Err((XmlError::InvalidUtf8,scan.utf8.start))}
442	    if p==scan.start{return if p==source.len(){Err((XmlError::InvalidName,scan.start))}else{Ok(None)}}
443	    if p==limit&&p<source.len(){return Ok(None)}
444	    if qname&&(scan.leading_colon||scan.trailing_colon){return Err((XmlError::InvalidName,scan.start))}
445	    let name=span(scan.start,p);let (prefix,local)=if let Some(c)=scan.first_colon{(span(scan.start,c),span(c+1,p))}else{(XmlSpan{offset:scan.start,length:0},name)};
446	    if qname&&scan.local_first_valid==Some(false){return Err((XmlError::InvalidName,local.offset))}
447	    Ok(Some(NameParts{name,prefix,local,xml_exact:p-scan.start==3&&scan.classification.xml_exact,xml_folded:p-scan.start==3&&scan.classification.xml_folded,entity_known:scan.classification.known_entity(p-scan.start)}))
448	}
