 75	fn collect_with_budget(source: &[u8], budget: usize) -> (ReaderStatus, ReaderProgress, Vec<ReaderTag>) {
 76	    let mut reader = XmlReader::new(source).expect("within source limit");
 77	    let mut tags = Vec::new();
 78	    loop {
 79	        let before = reader.progress().bytes_read;
 80	        let status = reader.step(budget, |tag| { tags.push(tag); true });
 81	        let progress = reader.progress();
 82	        assert!(progress.bytes_read - before <= budget.min(MAX_READER_STEP_BYTES));
 83	        if status != ReaderStatus::Ok { return (status, progress, tags); }
 84	    }
 85	}
